std::optional<std::string> mk64TlutArchivePathFor(const std::string& archivePath) {
    static const std::unordered_map<std::string, std::string> kMap = [] {
        std::unordered_map<std::string, std::string> map;
        map.reserve(std::size(kMk64TlutPairs));
        for (const auto& [ci, tlut] : kMk64TlutPairs) {
            map.emplace(ci, tlut);
        }
        return map;
    }();
    auto it = kMap.find(archivePath);
    if (it == kMap.end()) {
        return std::nullopt;
    }
    return it->second;
}

